where order_id = #{orderId}
order by item_id asc
limit #{limit}

select item_id, order_id, dish_id, dish_name, count
from (
    select item_id, order_id, dish_id, dish_name, count,
           row_number() over (partition by order_id order by item_id asc) as item_rank
    from meal_order_item
    where order_id in

        #{orderId}

) ranked_items
where item_rank <= #{limitPerOrder}
order by order_id asc, item_id asc

