status = #{status}, data_version = data_version + 1, accept_by = #{acceptBy}, accept_time = sysdate(), accept_user_id = #{acceptUserId}, finish_by = #{finishBy}, finish_time = sysdate(), cancel_time = sysdate(), close_reason = #{closeReason}, assign_mode = #{assignMode}, deadline_time = #{deadlineTime}, update_by = #{updateBy}, update_time = sysdate()
where order_id = #{orderId} and del_flag = '0'
and status = #{expectedStatus}
and data_version = #{expectedVersion}
and deadline_time is not null and deadline_time <= sysdate()

